name: Tests

on:
  pull_request:
    branches: [dev]
  push:
    branches: [dev]

concurrency:
  # Initial attempts share the ref stream so new heads still supersede old work.
  # Reruns retain their original run_id and cannot cancel a newer head (#15593).
  group: tests-${{ github.workflow }}-${{ github.run_attempt == '1' && github.ref || github.run_id }}
  cancel-in-progress: true


jobs:
  changes:
    name: Classify test scope
    runs-on: ubuntu-latest
    outputs:
      run_integration: ${{ steps.scope.outputs.run_integration }}
      run_unit: ${{ steps.scope.outputs.run_unit }}
      run_components: ${{ steps.scope.outputs.run_components }}
      run_parity: ${{ steps.scope.outputs.run_parity }}
      skip_reason: ${{ steps.scope.outputs.skip_reason }}

    steps:
      - name: Classify changed paths
        id: scope
        uses: actions/github-script@v9
        with:
          script: |
            const eventName = context.eventName;

            async function getChangedFiles() {
              if (eventName === 'pull_request') {
                const files = await github.paginate(github.rest.pulls.listFiles, {
                  owner      : context.repo.owner,
                  repo       : context.repo.repo,
                  pull_number: context.payload.pull_request.number,
                  per_page   : 100
                });

                return files.map(file => file.filename);
              }

              if (eventName === 'push') {
                const before = context.payload.before;
                const after  = context.payload.after;

                if (!before || !after || /^0+$/.test(before)) {
                  return null;
                }

                const comparison = await github.rest.repos.compareCommitsWithBasehead({
                  owner   : context.repo.owner,
                  repo    : context.repo.repo,
                  basehead: `${before}...${after}`,
                  per_page: 100
                });

                return comparison.data.files?.map(file => file.filename) || null;
              }

              return null;
            }

            async function isCurrentPullRequestHead() {
              if (eventName !== 'pull_request') {
                return true;
              }

              const pull = await github.rest.pulls.get({
                owner      : context.repo.owner,
                repo       : context.repo.repo,
                pull_number: context.payload.pull_request.number
              });
              const eventHead = context.payload.pull_request.head.sha;
              const liveHead  = pull.data.head.sha;

              if (eventHead === liveHead) {
                return true;
              }

              const reason = `stale workflow head ${eventHead}; live PR head is ${liveHead}`;

              core.notice(`Skipping expensive test suites: ${reason}`);
              core.setOutput('run_integration', 'false');
              core.setOutput('run_unit', 'false');
              core.setOutput('run_components', 'false');
              core.setOutput('run_parity', 'false');
              core.setOutput('skip_reason', reason);
              await core.summary
                .addHeading('Stale workflow attempt')
                .addRaw(`Skipped expensive test suites because ${reason}.`)
                .write();

              return false;
            }

            if (!await isCurrentPullRequestHead()) {
              return;
            }

            const files = await getChangedFiles();

            if (!files || files.length === 0) {
              core.info('Changed files are unavailable; running full test suites.');
              core.setOutput('run_integration', 'true');
              core.setOutput('run_unit', 'true');
              core.setOutput('run_components', 'true');
              core.setOutput('run_parity', 'true');
              core.setOutput('skip_reason', 'changed files unavailable');
              return;
            }

            const normalizedFiles = files.map(file => file.replace(/\\/g, '/'));

            // Keep explicit unit/integration statuses on docs-only PRs instead of
            // workflow-level paths-ignore. Missing checks can block protected branches.
            const isDocsOnlyPath = file =>
              file.endsWith('.md') ||
              file.startsWith('learn/') ||
              file.startsWith('resources/content/');

            // Unit has committed content guards, notably the release-note mutable
            // GitHub-link scan, discussion markdown fixture reads, and generated
            // portal index fixtures.
            const requiresUnitForContent = file =>
              file.startsWith('resources/content/release-notes/') ||
              file.startsWith('resources/content/discussions/') ||
              file.startsWith('apps/portal/resources/data/');

            // Whitelist: integration runs only on changes that can affect the integration
            // stack — engine (src/), Agent OS (ai/, incl. ai/deploy compose), the integration
            // specs/fixtures + shared test infra, dep manifests, or this workflow. Keep this
            // COMPLETE — a missed path silently skips integration (false-negative).
            const isIntegrationRelevantPath = file =>
              file.startsWith('src/') ||
              file.startsWith('ai/') ||
              file.startsWith('test/playwright/integration/') ||
              file.startsWith('test/playwright/util/') ||
              file === 'test/playwright/fixtures.mjs' ||
              file === 'test/playwright/setup.mjs' ||
              file === 'test/playwright/playwright.config.integration.mjs' ||
              file === 'package.json' ||
              file === 'package-lock.json' ||
              file === '.github/workflows/test.yml';

            // Whitelist: the components suite mounts real components in a browser against
            // the webpack dev server — engine (src/), live-compiled theme SCSS, the component
            // specs + their harness apps, the config chain, dep manifests, or this workflow.
            // Same completeness rule as integration: a missed path silently skips the suite
            // (#15368 — this suite ran in NO workflow at all until it was wired here).
            const isComponentsRelevantPath = file =>
              file.startsWith('src/') ||
              file.startsWith('resources/scss/') ||
              file.startsWith('test/playwright/component/') ||
              file === 'test/playwright/configTemplateResolver.mjs' ||
              file === 'test/playwright/playwright.config.component.mjs' ||
              file === 'package.json' ||
              file === 'package-lock.json' ||
              file === '.github/workflows/test.yml';

            // Whitelist (#15807): the parity lane is the single-reality witness for the
            // phase-3 stack — it boots ai/deploy/docker-compose.dev.yml (+ the parity-ci
            // overlay) on an overlay planeId and asserts topology + the mock-embedding
            // contract, FAILING CLOSED when docker is absent (never best-effort).
            //
            // Boundary, not a new list: the booted stack's runtime closure is the SAME
            // one the integration suite already treats as bootable — src/ (the engine
            // hemisphere the servers extend), ai/ (services, config chain, daemons,
            // deploy), the integration fixtures + harness. Parity relevance therefore
            // INHERITS isIntegrationRelevantPath and adds only the lane's own files.
            // One boundary, one owner: a future runtime import the integration
            // whitelist learns about is inherited here automatically; an invented
            // subset would drift the moment the stack crosses it (it already crosses
            // into src/state/Provider, src/core/Base, and the shared mcpClient fixture).
            const isParityRelevantPath = file =>
              isIntegrationRelevantPath(file) ||
              file.startsWith('test/playwright/integration-parity/') ||
              file === 'test/playwright/playwright.config.integration-parity.mjs';

            const runIntegration = normalizedFiles.some(isIntegrationRelevantPath);
            const runUnit        = normalizedFiles.some(file => !isDocsOnlyPath(file) || requiresUnitForContent(file));
            const runComponents  = normalizedFiles.some(isComponentsRelevantPath);
            const runParity      = normalizedFiles.some(isParityRelevantPath);

            core.info(`Changed files: ${normalizedFiles.join(', ')}`);
            core.info(`run_integration=${runIntegration}`);
            core.info(`run_unit=${runUnit}`);
            core.info(`run_components=${runComponents}`);
            core.info(`run_parity=${runParity}`);

            core.setOutput('run_integration', String(runIntegration));
            core.setOutput('run_unit', String(runUnit));
            core.setOutput('run_components', String(runComponents));
            core.setOutput('run_parity', String(runParity));
            core.setOutput(
              'skip_reason',
              'change does not touch relevant paths for this suite (docs/content/config or unrelated test suite)'
            );

  test:
    name: ${{ matrix.suite }}
    runs-on: ubuntu-latest
    needs: changes
    strategy:
      fail-fast: false
      matrix:
        # Bucket A-F audit (#10903) closed via #10907/#10921/#10910/#10919/#10920.
        # Bucket G (#10924) substrate fixes landed via #10940 (TestLifecycleHelper
        # primitive + daemon-spec migration) + open trackers for residual flakes
        # (#10941/#10936/#10937/#10946 — all unit-skip-guarded via NEO_TEST_SKIP_CI).
        #
        # Per-suite run flag resolves the classifier output once (#15368) — every
        # step below gates on `matrix.run` instead of re-enumerating suite×flag
        # boolean pairs, which stopped scaling at the third suite.
        include:
          - suite: integration-unified
            run: ${{ needs.changes.outputs.run_integration }}
          - suite: integration-parity
            run: ${{ needs.changes.outputs.run_parity }}
          - suite: unit
            run: ${{ needs.changes.outputs.run_unit }}
          - suite: components
            run: ${{ needs.changes.outputs.run_components }}

    steps:
      # Re-run failed jobs does not re-run successful prerequisite jobs. Keep this
      # job-local gate so an obsolete failed suite cannot consume a full runner.
      - name: Verify current pull-request head
        id: head
        uses: actions/github-script@v9
        with:
          script: |
            if (context.eventName !== 'pull_request') {
              core.setOutput('current', 'true');
              return;
            }

            const pull = await github.rest.pulls.get({
              owner      : context.repo.owner,
              repo       : context.repo.repo,
              pull_number: context.payload.pull_request.number
            });
            const eventHead = context.payload.pull_request.head.sha;
            const liveHead  = pull.data.head.sha;
            const current   = eventHead === liveHead;

            core.setOutput('current', String(current));

            if (!current) {
              const reason = `stale workflow head ${eventHead}; live PR head is ${liveHead}`;

              core.notice(`Skipping expensive test suite: ${reason}`);
              core.setOutput('skip_reason', reason);
              await core.summary
                .addHeading('Stale workflow attempt')
                .addRaw(`Skipped the expensive test suite because ${reason}.`)
                .write();
            }

      - name: Checkout repository
        if: ${{ matrix.run == 'true' && steps.head.outputs.current == 'true' }}
        uses: actions/checkout@v6

      - name: Setup Node.js
        if: ${{ matrix.run == 'true' && steps.head.outputs.current == 'true' }}
        uses: actions/setup-node@v6
        with:
          node-version: '24'
          cache: 'npm'

      # Pre-create .neo-ai-data so the `prepare` lifecycle's downloadKnowledgeBase
      # short-circuits via its existing-dir guard. Integration tests use a tmpfs
      # Chroma per `ai/deploy/docker-compose.test.yml`; unit tests are mocked; the
      # components suite runs browser-against-dev-server. No suite needs the
      # canonical KB artifact in CI.
      - name: Skip Knowledge Base download in prepare lifecycle
        if: ${{ matrix.run == 'true' && steps.head.outputs.current == 'true' }}
        run: mkdir -p .neo-ai-data

      - name: Install dependencies
        if: ${{ matrix.run == 'true' && steps.head.outputs.current == 'true' }}
        run: npm ci

      # Required for the unit-test runner per bootstrapWorktree.mjs precedent.
      # Harmless for the other suites.
      - name: Bundle parse5
        if: ${{ matrix.run == 'true' && steps.head.outputs.current == 'true' }}
        run: npm run bundle-parse5

      # The components suite launches real Chromium against the dev server; unit and
      # integration run browserless, so browser provisioning stays scoped to this suite.
      - name: Install Playwright Chromium
        if: ${{ matrix.run == 'true' && steps.head.outputs.current == 'true' && matrix.suite == 'components' }}
        run: npx playwright install --with-deps chromium

      - name: Skip ${{ matrix.suite }} tests
        if: ${{ matrix.run != 'true' || steps.head.outputs.current != 'true' }}
        run: |
          echo "${{ matrix.suite }} skipped: ${{ steps.head.outputs.skip_reason || needs.changes.outputs.skip_reason }}"

      - name: Run ${{ matrix.suite }} tests
        if: ${{ matrix.run == 'true' && steps.head.outputs.current == 'true' }}
        run: npm run test-${{ matrix.suite }}
        env:
          NEO_INTEGRATION_STACK_TIMEOUT_MS: '240000'
          # Keep the unit residual skip guards active without gating integration specs.
          NEO_TEST_SKIP_CI: ${{ matrix.suite == 'unit' && 'true' || '' }}

      - name: Upload test artifacts on failure
        if: ${{ failure() && matrix.run == 'true' && steps.head.outputs.current == 'true' }}
        uses: actions/upload-artifact@v4
        with:
          name: test-results-${{ matrix.suite }}-${{ github.run_id }}
          path: test/playwright/test-results/
          retention-days: 14
